export const DIPPER={alkaid:[160,232],mizar:[205,216],alioth:[250,232],megrez:[303,241],phecda:[309,279],merak:[375,277],dubhe:[375,241],polaris:[375,61]};
export function dipperSvg(pointer=false,targets=false){const p=DIPPER;const names=['alkaid','mizar','alioth','megrez','phecda','merak','dubhe'];return `<svg viewBox="100 0 450 310" role="img" aria-label="Seven stars in the Big Dipper. The two outside bowl stars point toward the North Star."><path d="M${p.alkaid} ${['mizar','alioth','megrez','phecda','merak','dubhe','megrez'].map(n=>'L'+p[n]).join(' ')}" fill="none" stroke="#a8c9f4" stroke-width="3"/>${pointer?`<path class="pointer-line" d="M375 277V61" fill="none" stroke="#ffdf87" stroke-width="4" stroke-dasharray="8 7"/><text x="392" y="153" fill="#ffdf87" font-size="14">NORTH ↑</text>`:''}${names.map(n=>`<circle cx="${p[n][0]}" cy="${p[n][1]}" r="${['merak','dubhe'].includes(n)?7:5}" fill="${['merak','dubhe'].includes(n)?'#ffdf87':'#e9faff'}"/>`).join('')}<circle cx="375" cy="61" r="8" fill="${pointer?'#ffdf87':'#cfddf4'}"/>${targets?'<text x="389" y="60" fill="white" font-size="19">A</text><circle cx="170" cy="70" r="7" fill="#cfddf4"/><text x="184" y="70" fill="white" font-size="19">B</text><circle cx="480" cy="200" r="7" fill="#cfddf4"/><text x="492" y="200" fill="white" font-size="19">C</text>':''}</svg>`;}
const svg=(body,label)=>`<svg viewBox="0 0 120 100" role="img" aria-label="${label}"><defs><radialGradient id="ball"><stop offset="0" stop-color="#e5fdff"/><stop offset=".5" stop-color="#67bde2"/><stop offset="1" stop-color="#285189"/></radialGradient><radialGradient id="sunball"><stop stop-color="#fff4ab"/><stop offset="1" stop-color="#ffb75b"/></radialGradient></defs>${body}</svg>`;
export function picture(name){
 if(name==='dipper')return dipperSvg();
 if(name==='earth'||name==='spin')return svg(`<g class="${name==='spin'?'spin':''}" style="transform-origin:60px 50px"><circle cx="60" cy="50" r="37" fill="url(#ball)"/><path d="m33 26 17 3 6 13-14 8 10 14-10 17-17-23 1-20m39-18 23 14-5 11-15 4 4 17-13 17-6-26 7-14-10-9Z" fill="#8be1b6"/></g>`,name==='spin'?'Spinning Earth':'Earth');
 if(name==='sun'||name==='day')return svg(`<g fill="#ffcd6c">${Array.from({length:12},(_,i)=>`<path d="M57 4h6l-3 15Z" transform="rotate(${i*30} 60 50)"/>`).join('')}</g><circle cx="60" cy="50" r="30" fill="url(#sunball)"/>`,name==='day'?'Bright sunshine':'Sun');
 if(['moon','full','new','half','phases','night'].includes(name)){if(name==='phases')return svg('<circle cx="25" cy="50" r="19" fill="#243852" stroke="#91a6c1"/><circle cx="60" cy="50" r="19" fill="#243852"/><path d="M60 31a19 19 0 0 1 0 38Z" fill="#fff1c7"/><circle cx="95" cy="50" r="19" fill="#fff1c7"/>','Moon phases');return svg(`<circle cx="60" cy="50" r="36" fill="${['new','night','half'].includes(name)?'#24334d':'#fff0c8'}" stroke="#9cacbe" stroke-width="2"/>${name==='half'?'<path d="M60 14a36 36 0 0 1 0 72Z" fill="#fff0c8"/>':''}${['moon','full'].includes(name)?'<g fill="#d9cca8"><circle cx="47" cy="33" r="8"/><circle cx="74" cy="57" r="11"/><circle cx="42" cy="68" r="5"/></g>':''}`,name==='new'?'Dark new moon':name==='full'?'Bright full moon':name==='half'?'Half-lit moon':'Moon');}
 if(name==='sphere')return svg('<circle cx="60" cy="48" r="36" fill="url(#ball)"/><ellipse cx="60" cy="90" rx="30" ry="4" fill="#050c2144"/>','3D ball');
 if(name==='circle')return svg('<circle cx="60" cy="50" r="36" fill="#78bde1"/>','Flat circle');
 if(name==='square')return svg('<rect x="25" y="15" width="70" height="70" fill="#f8ac9c"/>','Flat square');
 if(name==='orbit')return svg('<ellipse cx="60" cy="50" rx="50" ry="32" fill="none" stroke="#a6c6e5" stroke-dasharray="4 4"/><circle cx="60" cy="50" r="20" fill="url(#sunball)"/><circle cx="110" cy="50" r="10" fill="#71dbce"/>','Earth goes around the Sun');
 if(name==='clock'||name==='calendar')return svg(name==='clock'?'<circle cx="60" cy="50" r="37" fill="#fff2cb"/><path d="M60 23v27l20 10" fill="none" stroke="#34425e" stroke-width="6"/><text x="60" y="78" text-anchor="middle" font-size="17" fill="#34425e">24</text>':'<rect x="24" y="15" width="72" height="72" rx="10" fill="#e9edff"/><path d="M24 30h72" stroke="#b29ff7" stroke-width="20"/><text x="60" y="70" text-anchor="middle" font-size="34" fill="#34425e">28</text>',name==='clock'?'24-hour clock':'28-day calendar');
 if(name==='rise'||name==='set')return svg(`<path d="M10 72h100" stroke="#80d4bd" stroke-width="5"/><path d="M30 70a30 30 0 0 1 60 0" fill="#ffd076"/><text x="60" y="32" text-anchor="middle" font-size="18" fill="#fff">${name==='rise'?'EAST ↑':'WEST ↓'}</text>`,name==='rise'?'Sunrise in the east':'Sunset in the west');
 if(name==='star'||name==='north')return svg('<path d="m60 9 12 27 30 4-22 21 6 30-26-15-26 15 6-30-22-21 30-4Z" fill="#ffe296"/>','Star');
 if(name==='triangle'||name==='zigzag')return svg(`<path d="${name==='triangle'?'M20 80 60 15 100 80Z':'M15 25 45 65 75 25 105 65'}" fill="none" stroke="#c3d4fd" stroke-width="3"/>${(name==='triangle'?[[20,80],[60,15],[100,80]]:[[15,25],[45,65],[75,25],[105,65]]).map(([x,y])=>`<circle cx="${x}" cy="${y}" r="6" fill="#fff"/>`).join('')}`,name==='triangle'?'Triangle pattern':'Zigzag pattern');
 if(name==='polaris'||name==='decoy1'||name==='decoy2')return svg(`<circle cx="60" cy="45" r="19" fill="#ffe296"/><text x="60" y="87" text-anchor="middle" fill="white" font-size="22">${name==='polaris'?'A':name==='decoy1'?'B':'C'}</text>`,'Star '+(name==='polaris'?'A':name==='decoy1'?'B':'C'));
 return svg(`<text x="60" y="68" text-anchor="middle" font-size="54">${name==='cloud'?'☁':name==='sleep'?'💤':'✧'}</text>`,name);
}
export function demoMarkup(kind,step){
 if(kind==='clock')return `<svg viewBox="0 0 560 190" aria-label="An animated clock illustrates 24 hours, one full day"><circle cx="280" cy="85" r="66" fill="#fff0ca"/><g ${step?'class="spin" style="transform-box:view-box;transform-origin:280px 85px"':''}><path d="M280 35v50l35 12" fill="none" stroke="#344366" stroke-width="6"/></g><text x="280" y="140" text-anchor="middle" fill="#344366" font-size="21">24 hours</text><text x="280" y="181" text-anchor="middle" fill="white" font-size="18">ONE DAY • one full Earth rotation</text></svg>`;
 if(kind==='orbit')return `<svg viewBox="0 0 560 190" aria-label="Earth spins on itself while it travels around the Sun"><ellipse cx="280" cy="92" rx="105" ry="65" fill="none" stroke="#b2c6e4" stroke-dasharray="5 7"/><circle cx="280" cy="92" r="34" fill="#ffda80"/><g transform="translate(280 92)"><g>${step?'<animateMotion path="M-105 0a105 65 0 1 0 210 0a105 65 0 1 0-210 0" dur="9s" repeatCount="indefinite"/>':'<animateMotion path="M-105 0" dur="1s" fill="freeze"/>'}<g class="${step?'spin':''}"><circle r="21" fill="#64c4d8"/><path d="m-12-13 12-4 7 10-7 8 8 8-12 12-10-13Z" fill="#9ae3b4"/></g></g></g><text x="280" y="184" text-anchor="middle" fill="white" font-size="17">Earth spins AND travels around the Sun • one year</text></svg>`;

 if(['pointers','north'].includes(kind))return dipperSvg(step>0,kind==='north');
 if(['spin','light','night','sun','daystars'].includes(kind)){const night=kind==='daystars'?step%2===0:step%2===1;return `<svg viewBox="0 0 560 190" aria-label="Sunlight reaches one half of Earth. An explorer rotates between the light and dark sides."><rect width="560" height="190" rx="20" fill="${kind==='daystars'&&!night?'#81cfea':'#182745'}"/><circle cx="70" cy="92" r="40" fill="#ffd278"/><path d="M120 57h110m-110 36h110m-110 36h110" stroke="#ffd278" stroke-width="5" stroke-dasharray="9 7"/><g transform="translate(315 95)"><circle r="72" fill="#5ab8d7"/><g ${kind==='spin'&&step?'class="spin"':''}><path d="M-40-44-12-50 5-27-16-8-6 19-29 47-48 13Z" fill="#92e4b7"/></g><path d="M0-72a72 72 0 0 1 0 144Z" fill="#0c1b39bb"/>${step?`<circle cx="${night?44:-44}" cy="0" r="10" fill="#ffeaac"/><text x="${night?48:-48}" y="28" fill="white" font-size="14" text-anchor="middle">You</text>`:''}</g><text x="315" y="183" text-anchor="middle" fill="white" font-size="17">${kind==='daystars'?(night?'Night: stars are easier to see':'Day: stars are still there!'):step?(night?'Night for you. Day on the other side!':'You face the Sun: daytime!'):'Tap to turn Earth'}</text>${kind==='daystars'?Array.from({length:12},(_,i)=>`<circle cx="${440+(i*27)%100}" cy="${20+i*11}" r="2" fill="${night?'#fff':'#c7e5f077'}"/>`).join(''):''}</svg>`;}
 if(kind==='orbit'||kind==='moonOrbit'||kind==='phases'){const lunar=kind!=='orbit',angle=step*Math.PI/2+Math.PI,x=280+Math.cos(angle)*105,y=92+Math.sin(angle)*65;return `<svg viewBox="0 0 560 190" aria-label="${lunar?'Moon goes around Earth. Sunlight comes from the left.':'Earth goes around the Sun. Earth also spins.'}">${lunar?'<circle cx="35" cy="92" r="25" fill="#ffd278"/><path d="M70 65h75m-75 27h75m-75 27h75" stroke="#ffd278" stroke-width="3"/>':''}<ellipse cx="280" cy="92" rx="105" ry="65" fill="none" stroke="#b2c6e4" stroke-dasharray="5 7"/><circle cx="280" cy="92" r="${lunar?35:37}" fill="${lunar?'#5fc4ce':'#ffd278'}"/><g ${step&&kind==='orbit'?'class="spin" style="transform-origin:'+x+'px '+y+'px"':''}><circle cx="${x}" cy="${y}" r="20" fill="${lunar?'#fff0c8':'#5fc4ce'}"/><path d="M${x} ${y-20}a20 20 0 0 1 0 40Z" fill="${lunar?'#26314b':'#93e4b6'}"/></g><text x="280" y="180" text-anchor="middle" font-size="16" fill="white">${lunar?'Moon travels around Earth • about 28 days':'Earth travels around the Sun • one year'}</text>${kind==='phases'?`<g transform="translate(420 10) scale(.7)">${picture(['new','half','full','half'][step%4]).replace(/<\/?svg[^>]*>/g,'')}</g><text x="435" y="125" fill="white" font-size="13">View from Earth</text>`:''}</svg>`;}
 if(kind==='rise'||kind==='set')return `<svg viewBox="0 0 560 190"><rect width="560" height="190" rx="20" fill="#498ca8"/><path d="M20 140h520" stroke="#95dcb8" stroke-width="9"/><circle cx="${step%2?465:95}" cy="${step?100:140}" r="30" fill="#ffda80"/><text x="95" y="40" fill="white" text-anchor="middle" font-size="22">EAST ↑</text><text x="465" y="40" fill="white" text-anchor="middle" font-size="22">WEST ↓</text><text x="280" y="180" fill="white" text-anchor="middle" font-size="18">${step%2?'Sunset':'Sunrise'}</text></svg>`;
 if(kind==='sphere')return `<div class="shape-pair">${picture('circle')}${picture('sphere')}</div>`;
 return `<div class="shape-pair">${picture('star')}${picture('earth')}${picture('moon')}</div>`;
}
